use WebCommander\Resources\GiftCards\GiftCards;

$response = GiftCards::listGiftCards($client, ['email' => 'jane.doe@example.com', 'is_active' => 'true']);

foreach ($response->map['gift_cards'] as $card) {
    echo $card['id'], ' ', $card['code'], ' ', $card['balance'], ' of ', $card['initial_amount'], PHP_EOL;
}
